begin;
create or replace function public.studio_overview() returns jsonb language plpgsql security definer set search_path=public as $$declare result jsonb:='{}';start_month timestamptz:=date_trunc('month',now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata';begin
if auth.uid() is null then raise exception 'Forbidden';end if;
if has_permission('crm') then result=result||jsonb_build_object('active_clients',(select count(*) from customers where status='active'),'pending_inquiries',(select count(*) from inquiries where status='new'),'recent_inquiries',(select coalesce(jsonb_agg(t),'[]') from (select id,name,type,status,created_at from inquiries order by created_at desc limit 5)t));end if;
if has_permission('operations') then result=result||jsonb_build_object('active_subscriptions',(select count(*) from flower_subscriptions where status='active'),'today_deliveries',(select count(*) from delivery_records where delivery_date=(now() at time zone 'Asia/Kolkata')::date),'upcoming_events',(select coalesce(jsonb_agg(t),'[]') from(select id,name,event_date,status from events where event_date>=(now() at time zone 'Asia/Kolkata')::date and status<>'cancelled' order by event_date limit 6)t),'low_stock',(select count(*) from inventory_items i where status='active' and coalesce((select sum(quantity) from inventory_movements m where m.item_id=i.id),0)<=reorder_threshold));end if;
if has_permission('finance') then result=result||jsonb_build_object('revenue_month',((select coalesce(sum(total),0) from invoices where status='finalized' and created_at>=start_month)-(select coalesce(sum(amount),0)from credit_notes where created_at>=start_month)),'received_month',((select coalesce(sum(amount),0) from payments where created_at>=start_month)-(select coalesce(sum(amount),0)from payment_refunds where created_at>=start_month)),'outstanding',(select coalesce(sum(greatest(b.balance,0)),0)from invoice_balances b join invoices i on i.id=b.id where i.status='finalized'),'draft_invoices',(select count(*) from invoices where status='draft'),'monthly_sales',(select jsonb_agg(x order by month) from(select to_char(d,'YYYY-MM') as month,coalesce((select sum(total) from invoices where status='finalized' and date_trunc('month',created_at at time zone 'Asia/Kolkata')=d),0)-coalesce((select sum(amount)from credit_notes where date_trunc('month',created_at at time zone 'Asia/Kolkata')=d),0) as invoiced,coalesce((select sum(amount) from payments where date_trunc('month',created_at at time zone 'Asia/Kolkata')=d),0)-coalesce((select sum(amount)from payment_refunds where date_trunc('month',created_at at time zone 'Asia/Kolkata')=d),0) as collected from generate_series(date_trunc('month',now() at time zone 'Asia/Kolkata')-interval '5 months',date_trunc('month',now() at time zone 'Asia/Kolkata'),interval '1 month')d)x));end if;
return result;end$$;

commit;
